create unique index if not exists ux_professional_assignment_link_work_stream_item on public.ils_professional_work_assignment_links(work_stream,work_item_id); create table if not exists public.ils_professional_assignment_transaction_guard (id uuid primary key default gen_random_uuid(),work_stream text not null,work_item_id uuid not null,professional_user_id uuid not null,work_code text not null,decision text not null,reason_code text not null,checks jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_transaction_guard enable row level security; revoke all on public.ils_professional_assignment_transaction_guard from anon,authenticated; create or replace function public.ils_professional_assignment_transaction_guard(p_work_item_id uuid,p_work_stream text,p_professional_user_id uuid,p_work_code text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_decision public.ils_unified_assignment_decisions%rowtype; v_link public.ils_professional_work_assignment_links%rowtype; v_ok boolean:=false; begin if p_work_item_id is null or p_work_stream not in ('PROFESSIONAL','B2B') or p_professional_user_id is null or p_work_code is null then return jsonb_build_object('decision','BLOCK','reason_code','INVALID_INPUT'); end if; if auth.uid() is null or auth.uid() <> p_professional_user_id then return jsonb_build_object('decision','BLOCK','reason_code','AUTH_USER_MISMATCH'); end if; select * into v_decision from public.ils_unified_assignment_decisions where work_code=p_work_code and associate_user_id=p_professional_user_id and decision='ALLOW' and requires_supervision=false and requires_professional_review=false order by created_at desc limit 1 for update; if not found then return jsonb_build_object('decision','BLOCK','reason_code','NO_CURRENT_ALLOW'); end if; if p_work_stream='PROFESSIONAL' and not exists(select 1 from public.ils_professional_work_items where id=p_work_item_id and professional_user_id=p_professional_user_id) then return jsonb_build_object('decision','BLOCK','reason_code','WORK_OWNERSHIP_MISMATCH'); end if; if p_work_stream='B2B' and not exists(select 1 from public.ils_b2b_work_items where id=p_work_item_id and professional_user_id=p_professional_user_id) then return jsonb_build_object('decision','BLOCK','reason_code','WORK_OWNERSHIP_MISMATCH'); end if; select * into v_link from public.ils_professional_work_assignment_links where work_stream=p_work_stream and work_item_id=p_work_item_id for update; if found then return jsonb_build_object('decision','BLOCK','reason_code','DUPLICATE_ASSIGNMENT','link_id',v_link.id); end if; insert into public.ils_professional_work_assignment_links(work_item_id,work_stream,assignment_decision_id,work_code,professional_user_id,link_status) values(p_work_item_id,p_work_stream,v_decision.id,p_work_code,p_professional_user_id,'APPROVED') returning * into v_link; insert into public.ils_professional_assignment_transaction_guard(work_stream,work_item_id,professional_user_id,work_code,decision,reason_code,checks) values(p_work_stream,p_work_item_id,p_professional_user_id,p_work_code,'ALLOW','ASSIGNMENT_CREATED',jsonb_build_object('decision_id',v_decision.id,'link_id',v_link.id,'atomic_guard',true)); return jsonb_build_object('decision','ALLOW','reason_code','ASSIGNMENT_CREATED','link_id',v_link.id,'assignment_decision_id',v_decision.id); exception when unique_violation then return jsonb_build_object('decision','BLOCK','reason_code','DUPLICATE_ASSIGNMENT_RACE'); end $$; revoke all on function public.ils_professional_assignment_transaction_guard(uuid,text,uuid,text) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_transaction_guard(uuid,text,uuid,text) to authenticated;